import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  IconDashboard,
  IconTasks,
  IconProfile,
  IconPomodoro,
  IconBook,
  IconTrophy,
  IconCalendar,
  IconChecklist,
  IconStatistics,
  IconStudent,
} from '../assets/icons';
import { useLocation, useNavigate } from 'react-router-dom';

// Enhanced dock animations with circular reveal
const dockVariants = {
  hidden: { 
    scale: 0,
    opacity: 0,
    borderRadius: "100%",
    y: 20
  },
  visible: { 
    scale: 1,
    opacity: 1,
    borderRadius: "1rem",
    y: 0,
    transition: { 
      type: "spring", 
      stiffness: 400,
      damping: 30,
      mass: 1.2,
      staggerChildren: 0.08,
      duration: 0.6,
      ease: [0.23, 1, 0.32, 1]
    }
  },
  exit: {
    scale: 0,
    opacity: 0,
    borderRadius: "100%",
    y: 20,
    transition: {
      duration: 0.4,
      ease: [0.23, 1, 0.32, 1]
    }
  }
};

// Enhanced icon animations for mobile expansion
const mobileIconVariants = {
  closed: {
    scale: 1,
    opacity: 1,
    y: 0,
    rotate: 0,
    transition: {
      type: "spring",
      stiffness: 400,
      damping: 25
    }
  },
  open: {
    scale: 0.85,
    opacity: 0.3,
    y: 0,
    rotate: 180,
    transition: {
      type: "spring",
      stiffness: 400,
      damping: 25
    }
  }
};

const expandedIconsVariants = {
  hidden: {
    opacity: 0,
    scale: 0.3,
    y: 30,
  },
  visible: (i) => ({
    opacity: 1,
    scale: 1,
    y: 0,
    transition: {
      type: "spring",
      stiffness: 400,
      damping: 25,
      delay: i * 0.03,
    }
  }),
  exit: {
    opacity: 0,
    scale: 0.3,
    y: 30,
    transition: {
      duration: 0.15
    }
  }
};

// Enhanced neural network background effect
const NeuralBackground = () => (
  <div className="absolute inset-0 overflow-hidden rounded-inherit">
    <div className="absolute inset-0 bg-gradient-to-r from-blue-600/20 via-purple-600/20 to-pink-600/20 animate-gradient"></div>
    <svg className="absolute inset-0 w-full h-full opacity-50" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="neural-grad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="rgba(96, 165, 250, 0.3)" />
          <stop offset="50%" stopColor="rgba(167, 139, 250, 0.3)" />
          <stop offset="100%" stopColor="rgba(244, 114, 182, 0.3)" />
        </linearGradient>
      </defs>
      <pattern id="neural-pattern" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
        <circle cx="20" cy="20" r="1.5" fill="url(#neural-grad)">
          <animate attributeName="r" values="1;2;1" dur="2s" repeatCount="indefinite" />
        </circle>
      </pattern>
      <rect width="100%" height="100%" fill="url(#neural-pattern)" />
    </svg>
    <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_120%,rgba(120,119,198,0.3),rgba(255,255,255,0))]"></div>
  </div>
);

// Enhanced DockIcon component with better performance
const DockIcon = React.memo(({ icon: Icon, label, onClick, isActive, to, className = "", custom, variants }) => {
  const handleClick = React.useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    onClick(to);
  }, [onClick, to]);

  return (
    <motion.div
      className={`flex flex-col items-center justify-center cursor-pointer touch-manipulation relative ${className}`}
      whileHover={{ scale: 1.1, y: -3 }}
      whileTap={{ scale: 0.9 }}
      onClick={handleClick}
      onTouchEnd={handleClick}
      role="button"
      aria-label={`Navigate to ${label}`}
      aria-pressed={isActive}
      tabIndex={0}
      variants={variants}
      custom={custom}
      layout
    >
      {isActive && (
        <>
          <div className="absolute -inset-1 rounded-xl opacity-40 -z-10 bg-gradient-to-b from-blue-500/30 to-purple-600/30 blur-md animate-pulse-neural" />
          <div className="absolute -inset-2 rounded-xl opacity-20 -z-20 bg-gradient-to-b from-blue-500/20 to-purple-600/20 blur-lg" />
        </>
      )}
      
      <div 
        className={`relative p-3 rounded-xl overflow-hidden flex items-center justify-center transition-all duration-300 w-full group
          ${isActive 
            ? 'bg-gradient-to-b from-blue-500/50 to-purple-600/50 text-white shadow-lg border border-white/20 backdrop-blur-lg' 
            : 'bg-gray-800/40 text-gray-300 hover:text-white backdrop-blur-md border border-white/5 hover:border-white/20 hover:bg-gray-700/40'
          }`}
      >
        <Icon className={`w-6 h-6 transition-transform duration-300 group-hover:scale-110 ${isActive ? 'drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]' : ''}`} />
        
        {/* Hover glow effect */}
        <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none">
          <div className="absolute inset-0 bg-gradient-to-b from-blue-500/20 to-purple-600/20 blur-sm" />
        </div>
      </div>
      
      <span className={`text-xs mt-1.5 font-medium transition-all duration-300 ${isActive ? 'text-white scale-105' : 'text-gray-400 group-hover:text-white'}`}>
        {label}
      </span>
    </motion.div>
  );
});

DockIcon.displayName = 'DockIcon';

const DockBar = ({ activeTab, setActiveTab }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isExpanded, setIsExpanded] = useState(false);

  // All navigation items combined
  const allNavItems = [
    { id: 'dashboard', icon: IconDashboard, label: 'Home', path: '/dashboard' },
    { id: 'tasks', icon: IconTasks, label: 'Tasks', path: '/tasks' },
    { id: 'pomodoro', icon: IconPomodoro, label: 'Focus', path: '/pomodoro' },
    { id: 'books', icon: IconBook, label: 'Books', path: '/books' },
    { id: 'profile', icon: IconProfile, label: 'Profile', path: '/profile' },
    { id: 'calendar', icon: IconCalendar, label: 'Calendar', path: '/calendar' },
    { id: 'notes', icon: IconChecklist, label: 'Notes', path: '/notes' },
    { id: 'statistics', icon: IconStatistics, label: 'Stats', path: '/statistics' },
    { id: 'study', icon: IconStudent, label: 'Study', path: '/study' },
  ];

  useEffect(() => {
    const currentPath = location.pathname.replace('/', '') || 'dashboard';
    setActiveTab(currentPath);
  }, [location.pathname, setActiveTab]);

  const handleIconClick = (path) => {
    try {
      if (isExpanded) {
        setIsExpanded(false);
        navigate(path);
      } else {
        setIsExpanded(true);
      }
    } catch (error) {
      console.error("Navigation error:", error);
      navigate('/dashboard');
    }
  };

  return (
    <AnimatePresence>
      <motion.div
        className="fixed bottom-0 left-0 right-0 z-50 pb-safe-area-inset-bottom"
        variants={dockVariants}
        initial="hidden"
        animate="visible"
        exit="exit"
      >
        <div className="relative mx-auto max-w-md px-4 pb-6">
          <motion.div 
            className={`relative overflow-hidden transition-all duration-500 ${
              isExpanded 
                ? "bg-gradient-to-b from-gray-900/95 via-gray-800/95 to-gray-900/95 backdrop-blur-xl rounded-2xl border border-white/20 shadow-[0_0_40px_-5px_rgba(0,0,0,0.5)]" 
                : "bg-transparent"
            }`}
            style={{ 
              boxShadow: isExpanded ? '0 0 40px -5px rgba(0,0,0,0.5), 0 0 15px -3px rgba(0,0,0,0.3), inset 0 0 2px rgba(255,255,255,0.2)' : 'none'
            }}
            layout
          >
            {/* Neural network background - only show when expanded */}
            {isExpanded && <NeuralBackground />}

            <div className="relative z-10">
              {/* Center main icon */}
              <motion.div
                className="flex justify-center p-3"
                variants={mobileIconVariants}
                animate={isExpanded ? "open" : "closed"}
                layout
              >
                <DockIcon
                  icon={IconDashboard}
                  label={isExpanded ? "Close" : "Menu"}
                  isActive={false}
                  onClick={() => setIsExpanded(!isExpanded)}
                  to="/dashboard"
                  className={`w-16 ${!isExpanded ? 'hover:bg-white/5 active:bg-white/10 rounded-full p-2 shadow-lg' : ''}`}
                />
              </motion.div>

              {/* Expanded icons grid */}
              <AnimatePresence mode="wait">
                {isExpanded && (
                  <motion.div
                    className="grid grid-cols-3 gap-4 p-4 pt-0"
                    initial="hidden"
                    animate="visible"
                    exit="exit"
                    layout
                  >
                    {allNavItems.map((item, index) => (
                      <motion.div
                        key={item.path}
                        variants={expandedIconsVariants}
                        custom={index}
                        layout
                      >
                        <DockIcon
                          icon={item.icon}
                          label={item.label}
                          isActive={activeTab === item.id}
                          onClick={handleIconClick}
                          to={item.path}
                        />
                      </motion.div>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

export default DockBar; 